<?php
use Illuminate\Validation\Rule; use Livewire\Component;
new class extends Component { public string $name='';public ?string $email='';public string $current_password='';public string $password='';public string $password_confirmation='';public function mount():void{$this->name=auth()->user()->name;$this->email=auth()->user()->email;}
public function saveProfile():void{$u=auth()->user();$d=$this->validate(['name'=>'required|string|max:255','email'=>['nullable','email',Rule::unique('users','email')->ignore($u->id)]]);$u->update($d);session()->flash('success','Profil berhasil diperbarui.');}
public function savePassword():void{$this->validate(['current_password'=>['required','current_password'],'password'=>'required|min:8|confirmed']);auth()->user()->update(['password'=>$this->password]);$this->reset('current_password','password','password_confirmation');session()->flash('success','Password berhasil diubah.');}}; ?>
<div><div class="mb-6"><p class="text-sm font-semibold text-sky-700">Akun</p><h1 class="page-title">Profil Saya</h1><p class="page-subtitle">Perbarui informasi akun dan keamanan password.</p></div><div class="grid gap-6 xl:grid-cols-2"><form wire:submit="saveProfile" class="card card-body space-y-5"><h2 class="text-lg font-semibold">Informasi Profil</h2><div><label class="form-label">Nama <span>*</span></label><input wire:model="name" class="form-input">@error('name')<p class="form-error">{{$message}}</p>@enderror</div><div><label class="form-label">Email</label><input type="email" wire:model="email" class="form-input">@error('email')<p class="form-error">{{$message}}</p>@enderror</div><button class="btn-primary">Simpan Profil</button></form><form wire:submit="savePassword" class="card card-body space-y-5"><h2 class="text-lg font-semibold">Ganti Password</h2><div><label class="form-label">Password Saat Ini <span>*</span></label><input type="password" wire:model="current_password" class="form-input">@error('current_password')<p class="form-error">{{$message}}</p>@enderror</div><div><label class="form-label">Password Baru <span>*</span></label><input type="password" wire:model="password" class="form-input">@error('password')<p class="form-error">{{$message}}</p>@enderror</div><div><label class="form-label">Konfirmasi Password <span>*</span></label><input type="password" wire:model="password_confirmation" class="form-input"></div><button class="btn-primary">Ubah Password</button></form></div></div>
